"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["7538"],{5699(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>u,frontMatter:()=>r,contentTitle:()=>c,toc:()=>h,assets:()=>l});var s=JSON.parse('{"id":"m14-working-with-coding-agents/lesson","title":"Lesson: Working Effectively with Coding Agents","description":"Since M3, every lab has included an \\"agent-extended\\" phase: you wrote a precise description of what","source":"@site/docs/m14-working-with-coding-agents/lesson.md","sourceDirName":"m14-working-with-coding-agents","slug":"/m14-working-with-coding-agents/lesson","permalink":"/307-aipython-site/docs/m14-working-with-coding-agents/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Working Effectively with Coding Agents"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/307-aipython-site/docs/m13-project-structure-quality/deep-dive"},"next":{"title":"Lab: Working Effectively with Coding Agents","permalink":"/307-aipython-site/docs/m14-working-with-coding-agents/lab"}}'),i=n(4848),o=n(8453),a=n(7684);let r={sidebar_position:1,title:"Lesson: Working Effectively with Coding Agents"},c="Working Effectively with Coding Agents",l={},h=[{value:"1. A spec is a contract, not a conversation",id:"1-a-spec-is-a-contract-not-a-conversation",level:2},{value:"2. Small changes, tight scope",id:"2-small-changes-tight-scope",level:2},{value:"3. The six flaws agents produce reliably",id:"3-the-six-flaws-agents-produce-reliably",level:2},{value:"4. Reading a diff is the actual skill",id:"4-reading-a-diff-is-the-actual-skill",level:2}];function d(e){let t={admonition:"admonition",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.A,{src:"decks/m14-concepts.html",title:"M14 \u2014 Working Effectively with Coding Agents"}),"\n",(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"working-effectively-with-coding-agents",children:"Working Effectively with Coding Agents"})}),"\n",(0,i.jsx)(t.p,{children:'Since M3, every lab has included an "agent-extended" phase: you wrote a precise description of what\nyou wanted, a coding agent implemented it, and you reviewed the result. That pattern -- describe,\ndelegate, review -- is the one real skill this module teaches. Everything else is a variation on it.'}),"\n",(0,i.jsx)(t.p,{children:"A coding agent is not a colleague who understands your project. It is closer to a contractor you\nhired for one specific job: the quality of what you get back depends almost entirely on how clearly\nyou described the work, what constraints you set, and how carefully you inspect the result. This\nmodule makes that process explicit and repeatable, so you can use it on any task, with any agent,\nand catch the mistakes agents make most often before those mistakes reach your tests or your users."}),"\n",(0,i.jsx)(t.h2,{id:"1-a-spec-is-a-contract-not-a-conversation",children:"1. A spec is a contract, not a conversation"}),"\n",(0,i.jsxs)(t.p,{children:['Think about hiring a contractor to add a room to your house. You would not just say "add a room"\nand hope for the best. You would hand them a written scope: what the room is for, where it\nconnects to the existing structure, which materials are approved, what the building code requires,\nand how you will inspect the result. A ',(0,i.jsx)(t.strong,{children:"specification"})," for a coding agent works the same way --\nit is a short, written document that answers four questions before the agent writes a single line:"]}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"What does it do?"})," A plain description of the feature or fix, stated as behavior the user\ncan observe, not as implementation steps."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"What can change?"})," The exact list of files the agent is allowed to modify or create. Anything\nnot on this list is off limits."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"What is approved?"})," Dependencies, patterns, and approaches the agent may use. If Flask is not\non this list, the agent should not add it."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"How do I know it worked?"}),' Acceptance criteria -- concrete checks the result must pass. "All\nexisting tests still pass" is always one of them.']}),"\n"]}),"\n",(0,i.jsxs)(t.p,{children:["The reason a written spec works better than a conversation is not about formality. It is about\n",(0,i.jsx)(t.strong,{children:"anchoring"}),". When an agent has a written constraint list, it refers back to that list while it\nworks. When it only has a conversational prompt, it drifts -- the constraint you mentioned three\nmessages ago fades from its working context the same way a verbal instruction fades from a\ncontractor's memory after lunch."]}),"\n",(0,i.jsx)(t.h2,{id:"2-small-changes-tight-scope",children:"2. Small changes, tight scope"}),"\n",(0,i.jsx)(t.p,{children:"Picture reviewing a one-page memo versus a fifty-page report. The memo takes two minutes; you\ncatch every mistake. The fifty-page report takes an hour, your attention drifts halfway through,\nand you miss a factual error on page thirty-seven."}),"\n",(0,i.jsx)(t.p,{children:'Agent-generated code works the same way. A diff that touches three files and adds forty lines is\nsomething you can read carefully, verify against the spec, and accept or reject with confidence.\nA diff that touches fifteen files, adds a new dependency, reorganizes two modules, and\n"improves" code you did not ask it to touch is almost impossible to review well -- and the\nmistakes hide in the parts you skim.'}),"\n",(0,i.jsxs)(t.p,{children:["The rule is simple: ",(0,i.jsx)(t.strong,{children:"one feature per request, with an explicit list of files that may change."}),"\nIf the agent's diff touches a file you did not list, that is a finding, regardless of whether the\nchange looks correct. Scope creep in an agent's output is exactly as dangerous as scope creep in\na contractor's invoice."]}),"\n",(0,i.jsx)(t.h2,{id:"3-the-six-flaws-agents-produce-reliably",children:"3. The six flaws agents produce reliably"}),"\n",(0,i.jsx)(t.p,{children:"Coding agents are good at producing code that compiles, passes a basic smoke test, and looks\nreasonable at first glance. They are systematically weak at six specific things, because those\nthings require context the agent either does not have or does not prioritize:"}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Missing timeouts"})," -- the agent calls an HTTP endpoint or runs a subprocess without setting\na timeout. The code works in testing (where the server answers fast) and hangs in production\n(where the server is overloaded or unreachable)."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Logged credentials"}),' -- the agent adds a log line that includes a token or key value. It is\ntrying to be helpful ("here is what we sent"), but the credential now appears in every log\nfile, every CI output, every terminal session that runs this code.']}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Swallowed exceptions"})," -- the agent writes ",(0,i.jsx)(t.code,{children:"except Exception: pass"})," or ",(0,i.jsx)(t.code,{children:"except: pass"}),' to\n"handle" an error. The error is now invisible. The function returns ',(0,i.jsx)(t.code,{children:"None"})," or an empty\nresult, and the caller has no way to know something went wrong."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Hallucinated APIs"}),' -- the agent imports a module or calls a function that does not exist in\nyour project or in any installed package. It looks correct because the name is plausible\n("of course there would be a ',(0,i.jsx)(t.code,{children:"platformops.cloud"}),' module"), but it fails on the first import.']}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Needless dependencies"})," -- the agent adds a package to solve a problem that existing tools\nalready handle. Adding ",(0,i.jsx)(t.code,{children:"requests"})," when the project already uses ",(0,i.jsx)(t.code,{children:"httpx"}),", or adding ",(0,i.jsx)(t.code,{children:"flask"}),"\nfor a feature that is entirely CLI-based, are both real examples."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Destructive defaults"})," -- the agent writes a cleanup function that deletes a directory\nwithout asking for confirmation, or a reset function that drops data without a dry-run\noption. The code works as written -- and the first time someone runs it on the wrong\ndirectory, it destroys real data."]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"None of these are rare. You will see at least one of them in almost every non-trivial agent diff.\nThe lab gives you practice finding all six in a single, realistic patch."}),"\n",(0,i.jsx)(t.h2,{id:"4-reading-a-diff-is-the-actual-skill",children:"4. Reading a diff is the actual skill"}),"\n",(0,i.jsxs)(t.p,{children:['When you delegate implementation to an agent, your job shifts from "write code" to "review code\ncritically." The output of that delegation is a ',(0,i.jsx)(t.strong,{children:"diff"})," -- a line-by-line record of what changed.\nEvery line in that diff needs a reason to exist, and your job is to ask three questions of each\nchange:"]}),"\n",(0,i.jsxs)(t.ol,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Is this what I asked for?"}),' Does the change match the spec? If the spec said "modify\n',(0,i.jsx)(t.code,{children:"scripts/check-deps.sh"}),'" and the diff also modifies ',(0,i.jsx)(t.code,{children:"src/platformops/cli.py"}),", that is a\nscope violation."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Is this safe?"})," Does the change introduce any of the six common flaws? A missing timeout,\na logged credential, a swallowed exception?"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Is this necessary?"})," Does every new line serve the feature? A new dependency, a new import,\na refactored function you did not ask to refactor -- each one is a question, not an\nautomatic accept."]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"This is the same discipline code review has always required. The difference is that an agent\nproduces code faster than a human does, so the review queue fills up faster. If you let review\nquality drop to keep up with the agent's output speed, you lose the entire benefit of having the\nagent in the first place."}),"\n",(0,i.jsx)(t.mermaid,{value:'flowchart LR\n    A["Write spec\\n(what, constraints,\\nacceptance criteria)"] --\x3e B["Delegate\\nto agent"]\n    B --\x3e C["Read the diff\\nline by line"]\n    C --\x3e D{Every line\\naccounted for?}\n    D --\x3e|"yes"| E["Accept +\\nrun tests"]\n    D --\x3e|"no"| F["Reject +\\nrevise spec"]\n    F --\x3e B'}),"\n",(0,i.jsx)(t.admonition,{title:"Common pitfalls",type:"tip",children:(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Reviewing at the speed the agent writes."})," An agent can produce a 200-line diff in thirty\nseconds. Reviewing it properly still takes ten minutes. If you accept without reading, you are\nnot delegating -- you are rubber-stamping."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:'Trusting "all tests pass" as proof of correctness.'})," Tests verify the paths they cover. A\nmissing timeout, a logged credential, or a swallowed exception can all coexist with a green\ntest suite. The review catches what tests do not."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Skipping the scope check."})," The agent modified a file you did not list in the spec. It might\nbe a legitimate need -- or it might be scope creep. Ask why before you accept."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Accepting a hallucinated import because the name looks right."})," ",(0,i.jsx)(t.code,{children:"platformops.cloud"})," sounds\nlike it should exist. It does not. Verify every new import against the actual codebase."]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Not writing the spec at all."}),' A conversational prompt ("add JSON output to check-deps")\ndrifts faster than a written spec. The five minutes you save by skipping the spec cost you\nthirty minutes of review when the agent\'s output does not match what you had in mind.']}),"\n"]})})]})}function u(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},7684(e,t,n){n.d(t,{A:()=>o});var s=n(4848);n(6540);var i=n(6497);function o({src:e,title:t="Slides"}){let n=(0,i.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,s.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var s=n(6540);let i={},o=s.createContext(i);function a(e){let t=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(o.Provider,{value:t},e.children)}}}]);